package uk.buzzlab;
import org.json.*; import java.io.*; import java.util.*; import java.util.zip.*;
/** Export and import. Exports use phyphox's CSV layout so existing scripts read them. */
final class Io {
  static void text(ZipOutputStream z,String n,String s) throws IOException { z.putNextEntry(new ZipEntry(n)); z.write(s.getBytes()); z.closeEntry(); }
  static void export(Store st,List<JSONObject> ds,OutputStream os,boolean positions) throws Exception { export(st,ds,os,positions,null); }
  /** extra: when given, a full export with plates and these additional files. */
  static void export(Store st,List<JSONObject> ds,OutputStream os,boolean positions,Map<String,String> extra) throws Exception {
    try(ZipOutputStream z=new ZipOutputStream(new BufferedOutputStream(os))){ text(z,"cars.json",(extra!=null?st.cars():strip(st.cars())).toString(1)); if(extra!=null)for(Map.Entry<String,String> x:extra.entrySet())text(z,x.getKey(),x.getValue()); JSONArray idx=new JSONArray();
      for(JSONObject m:ds){ File d=st.driveDir(m.getString("id")); String p="drives/"+m.getString("id")+"/"; idx.put(m); text(z,p+"meta.json",m.toString(1)); text(z,p+"stats.json",Dsp.load(d).json().toString()); Dsp.Raw r=Dsp.raw(d); double[] t=r.t; float[][] v=r.v;
        z.putNextEntry(new ZipEntry(p+"Accelerometer.csv")); Writer w=new BufferedWriter(new OutputStreamWriter(z),1<<16); w.write("\"Time (s)\",\"Acceleration x (m/s^2)\",\"Acceleration y (m/s^2)\",\"Acceleration z (m/s^2)\"\n"); for(int i=0;i<t.length;i++)w.write(String.format(Locale.UK,"%.6f,%.6f,%.6f,%.6f\n",t[i],v[i][0],v[i][1],v[i][2])); w.flush(); z.closeEntry();
        long base; try(DataInputStream in=new DataInputStream(new FileInputStream(new File(d,"acc.bin")))){base=in.readLong();} StringBuilder s=new StringBuilder("\"Time (s)\",\"Latitude\",\"Longitude\",\"Height (m)\",\"Velocity (m/s)\",\"Direction\",\"Horizontal Accuracy (m)\",\"Vertical Accuracy (m)\"\n"); for(String l:new String(java.nio.file.Files.readAllBytes(new File(d,"gps.csv").toPath())).split("\n")){ String[] q=l.split(",",-1); if(q.length<6||q[0].startsWith("t"))continue; s.append(String.format(Locale.UK,"%.3f",(Long.parseLong(q[0])-base)/1e9)).append(',').append(positions?q[1]:"NaN").append(',').append(positions?q[2]:"NaN").append(",NaN,").append(q[3].isEmpty()?"NaN":q[3]).append(',').append(positions&&!q[5].isEmpty()?q[5]:"NaN").append(',').append(q[4]).append(",NaN\n"); } text(z,p+"Location.csv",s.toString()); File mk=new File(d,"marks.csv"); if(mk.exists())text(z,p+"marks.csv",marks(mk,base)); }
      text(z,"drives.json",idx.toString(1)); } }
  static String marks(File f,long base) throws IOException { StringBuilder s=new StringBuilder("t_s,label\n"); for(String l:Store.read(f).split("\n")){ int k=l.indexOf(','); if(k<1||l.startsWith("t"))continue; s.append(String.format(Locale.UK,"%.2f",(Long.parseLong(l.substring(0,k))-base)/1e9)).append(l.substring(k)).append('\n'); } return s.toString(); }
  /** Number plates stay on the phone. */
  static JSONArray strip(JSONArray a) throws JSONException { JSONArray b=new JSONArray(); for(int i=0;i<a.length();i++){ JSONObject o=new JSONObject(a.getJSONObject(i).toString()); o.remove("reg"); b.put(o);} return b; }
  static String importPhyphox(Store st,InputStream is,String car,String place,String note,String tyre) throws Exception {
    Map<String,byte[]> m=new HashMap<>(); long total=0; try(ZipInputStream z=new ZipInputStream(new BufferedInputStream(is))){ ZipEntry e; while((e=z.getNextEntry())!=null){ String n=e.getName(); n=n.substring(n.lastIndexOf('/')+1); if(!n.equals("Accelerometer.csv")&&!n.equals("Location.csv")&&!n.equals("time.csv"))continue; ByteArrayOutputStream b=new ByteArrayOutputStream(); byte[] q=new byte[65536];int k; while((k=z.read(q))>0){ total+=k; if(total>400L<<20)throw new IOException("zip too large"); b.write(q,0,k);} m.put(n,b.toByteArray()); } }
    if(!m.containsKey("Accelerometer.csv")||!m.containsKey("Location.csv"))throw new IOException("not a phyphox export with GPS");
    long start=System.currentTimeMillis(); if(m.containsKey("time.csv"))for(String l:new String(m.get("time.csv")).split("\n"))if(l.contains("START"))start=(long)(Double.parseDouble(l.split(",")[2])*1000);
    for(JSONObject o:st.list())if(o.optLong("start")==start)throw new IOException("already imported");
    String id=""+start; File d=st.driveDir(id); d.mkdirs(); long n=0; double last=0;
    try(BufferedReader r=new BufferedReader(new InputStreamReader(new ByteArrayInputStream(m.get("Accelerometer.csv"))));DataOutputStream o=new DataOutputStream(new BufferedOutputStream(new FileOutputStream(new File(d,"acc.bin")),1<<16))){ r.readLine(); String l; while((l=r.readLine())!=null){ String[] p=l.split(","); if(p.length<4)continue; last=Double.parseDouble(p[0]); o.writeLong((long)(last*1e9)); for(int k=1;k<4;k++)o.writeFloat(Float.parseFloat(p[k])); n++; } }
    int fx=0; try(BufferedReader r=new BufferedReader(new InputStreamReader(new ByteArrayInputStream(m.get("Location.csv"))));PrintWriter o=new PrintWriter(new FileWriter(new File(d,"gps.csv")))){ r.readLine(); o.println("t_ns,lat,lon,speed_ms,acc_m,bearing"); String l; while((l=r.readLine())!=null){ String[] p=l.split(",",-1); if(p.length<7)continue; o.println((long)(Double.parseDouble(p[0])*1e9)+","+p[1]+","+p[2]+","+(p[4].equals("NaN")?"":p[4])+","+p[6]+","+(p[5].equals("NaN")?"":p[5])); fx++; } }
    st.saveMeta(new JSONObject().put("id",id).put("start",start).put("end",start+(long)(last*1000)).put("car",car).put("place",place).put("note",note).put("tyre",tyre).put("samples",n).put("fixes",fx).put("imported","phyphox").put("recording",false)); return id; }
}
